# 仅在输入为 INT8 时填充 extra_args，让算子内部处理反量化

    def full_graph_fia(self, query, key, value, layer, attn_params):
        """Full graph FIA attention with optional C8 quantization."""
        dtype = query.dtype
        extra_args = {}

        if self.enable_c8_quant and key.dtype == torch.int8:
            extra_args = {
                "key_antiquant_scale": layer._c8_k_aq_scale,
                "key_antiquant_offset": layer._c8_k_aq_offset,
                "value_antiquant_scale": layer._c8_v_aq_scale,
                "value_antiquant_offset": layer._c8_v_aq_offset,
                "key_antiquant_mode": 0,
                "value_antiquant_mode": 0,
            }

        return self._run_fia(query, key, value, extra_args, attn_params)
